const searchAssetsByKindForUser = `-- name: SearchAssetsByKindForUser :many
SELECT a.id, a.organization_id, a.project_id, a.owner_user_id, a.parent_id, a.name, a.kind, a.media_type, a.content_hash, a.size_bytes, a.visibility, a.source_type, a.source_artifact_id, a.created_at, a.updated_at
FROM assets a
JOIN memberships m ON m.organization_id = a.organization_id
JOIN project_memberships pm ON pm.project_id = a.project_id AND pm.user_id = m.user_id
WHERE a.organization_id = ?
  AND a.project_id = ?
  AND instr(lower(a.name), lower(?)) > 0
  AND a.kind = ?
  AND m.user_id = ?
  AND m.status = 'active'
  AND pm.status = 'active'
  AND (a.visibility = 'project' OR a.owner_user_id = ?)
ORDER BY a.updated_at DESC, a.id DESC
LIMIT ?
`

type SearchAssetsByKindForUserParams struct {
	OrganizationID string `json:"organization_id"`
	ProjectID      string `json:"project_id"`
	LOWER          string `json:"LOWER"`
	Kind           string `json:"kind"`
	UserID         string `json:"user_id"`
	OwnerUserID    string `json:"owner_user_id"`
	Limit          int64  `json:"limit"`
}

func (q *Queries) SearchAssetsByKindForUser(ctx context.Context, arg SearchAssetsByKindForUserParams) ([]Asset, error) {
	rows, err := q.db.QueryContext(ctx, searchAssetsByKindForUser,
		arg.OrganizationID,
		arg.ProjectID,
		arg.LOWER,
		arg.Kind,
		arg.UserID,
		arg.OwnerUserID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Asset{}
	for rows.Next() {
		var i Asset
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ProjectID,
			&i.OwnerUserID,
			&i.ParentID,
			&i.Name,
			&i.Kind,
			&i.MediaType,
			&i.ContentHash,
			&i.SizeBytes,
			&i.Visibility,
			&i.SourceType,
			&i.SourceArtifactID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

